:root {
  --ink: #29233a;
  --paper: #fffdf7;
  --plum: #50355d;
  --lilac: #eee7f4;
  --gold: #d99c45;
  --mint: #dcefe5;
  --line: #d9cfe0;
  --muted: #786d82;
}

.census-card {
  width: 450px;
  box-sizing: border-box;
  padding: 16px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}

.moth-mark {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 12px;
  background: var(--plum);
  color: var(--gold);
  font-size: 19px;
}

.title-group {
  min-width: 0;
  flex: 1;
}

.eyebrow,
.section-label {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  line-height: 1.2;
}

.title-group h1 {
  margin: 3px 0 0;
  font-size: 20px;
  font-weight: 750;
  letter-spacing: -0.4px;
  line-height: 1.1;
}

.date-chip {
  padding: 6px 8px;
  border-radius: 8px;
  background: var(--lilac);
  color: var(--plum);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.observation {
  display: grid;
  grid-template-columns: 1.3fr 0.9fr;
  gap: 12px;
  padding: 14px 0;
}

.site-details {
  padding: 12px;
  border-radius: 12px;
  background: var(--lilac);
}

.site-name {
  margin: 7px 0 2px;
  font-size: 15px;
  font-weight: 750;
  line-height: 1.2;
}

.site-meta,
.condition {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.35;
}

.count-panel {
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
}

.count {
  margin: 4px 0 1px;
  color: var(--plum);
  font-size: 25px;
  font-weight: 800;
  letter-spacing: -0.8px;
  line-height: 1;
}

.count span {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.status {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 650;
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--gold);
}

.log-button {
  padding: 8px 11px;
  border: 0;
  border-radius: 9px;
  background: var(--plum);
  color: var(--paper);
  font-size: 12px;
  font-weight: 750;
  line-height: 1;
}

.log-button span {
  margin-left: 5px;
  color: var(--gold);
  font-size: 15px;
}
